//! Well-formedness agreement with a real XML parser.
//!
//! `fixtures/wellformed.tsv` is generated by `scripts/fuzz/xmlkit/gen.py`, which
//! asks Python's `expat` whether each document is well-formed. expat is an
//! independent, widely used parser, so any disagreement is a bug in this crate.
//!
//! The corpus is half valid documents and half single mutations of one, so
//! acceptance is tested as hard as rejection. The one behaviour the crate
//! deliberately does not share with expat - a bare `&` that begins no entity is
//! kept as text, the npm `@xmldom/xmldom` behaviour this crate's consumers need -
//! is excluded by the generator, which normalises such an ampersand to `&amp;`
//! before recording expat's verdict. That leniency is asserted in `src/lib.rs`.

use xmlkit::parse;

/// The fixture: a verdict (`ok` or `err`) and a backslash-escaped document.
fn fixture() -> Vec<(&'static str, String)> {
    let text = include_str!("fixtures/wellformed.tsv");
    text.lines()
        .filter(|line| !line.starts_with('#') && !line.trim().is_empty())
        .map(|line| {
            let (verdict, document) = line.split_once('\t').expect("verdict and document");
            (verdict, unescape(document))
        })
        .collect()
}

/// The inverse of the generator's escaping, applied one character at a time.
fn unescape(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut chars = text.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next() {
            Some('n') => out.push('\n'),
            Some('t') => out.push('\t'),
            Some('\\') => out.push('\\'),
            Some(other) => {
                out.push('\\');
                out.push(other);
            }
            None => out.push('\\'),
        }
    }
    out
}

#[test]
fn every_case_agrees_with_expat() {
    let cases = fixture();
    assert!(cases.len() > 1000, "the fixture looks truncated");
    let mut disagreements = Vec::new();
    for (verdict, document) in &cases {
        let expected = *verdict == "ok";
        let actual = parse(document).is_ok();
        if expected != actual {
            disagreements.push(format!(
                "expected {} but got {}: {document:?}",
                if expected { "ok" } else { "err" },
                if actual { "ok" } else { "err" },
            ));
        }
    }
    assert!(
        disagreements.is_empty(),
        "{} of {} cases disagree with expat:\n{}",
        disagreements.len(),
        cases.len(),
        disagreements
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n"),
    );
}
